-- 목적: book_text 페이지 단위 본문 적재 (asb · 이 파일: 1of11)
-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D1·D2·D4·D5) · Accepted 2026-08-10
-- source 라벨: manifest_txt_v1
-- 이 파일 담당: 48권 / 478행 (정제 후 빈 면 0행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 48
SELECT count(*) AS books_found FROM books
  WHERE source_platform='african_storybook' AND source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892');

-- ───────── [적재] ─────────
BEGIN;
INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$manifest_txt_v1$$
  FROM (VALUES
    ('10196', 0, $$There lived a woman.$$),
    ('10196', 1, $$She had a baby and a pet cat.$$),
    ('10196', 2, $$It was a wonder cat, it could signal to the master whenever the baby cried.$$),
    ('10196', 3, $$One day the master went for a safari, on her return the pet cat seemed to have forgotten its usual behavior, the mother watched for a signal but to know avail.$$),
    ('10196', 4, $$The cat was busy liking its mouth parts and paws that were stained with blood.$$),
    ('10196', 5, $$Disturbed with this sight, mother baby searched the house but could not see the baby but only blood stained bed sheets.$$),
    ('10196', 6, $$She reached for the gun and targeted to finish the cat, fortunately the bullet missed the gun fire woke up the baby who was deep a sleep.$$),
    ('10196', 7, $$Beside the bed, there lay a big snake that the cat had fought and successfully killed.$$),
    ('10198', 0, $$A crow was thirsty. He moved a very long distance in search for water for drinking but failed.$$),
    ('10198', 1, $$He then tried to fly back. To the tree where he was living. It took him a long time because he was weak.$$),
    ('10198', 2, $$As he was moving he saw water in a pot in someone's compound.$$),
    ('10198', 3, $$The water was almost at the bottom of the pot. His beak could not reach the water in the pot. He thought of a way to get that water.$$),
    ('10198', 4, $$An idea came to his mind. Hegot small stones He dropped one stone and the water in the pot jumped.$$),
    ('10198', 5, $$The crow put his mouth and drunk the water droplets.$$),
    ('10198', 6, $$He got another stone and repeated the exercise. He kept on doing this until he was satisfied.$$),
    ('10201', 0, $$Once upon a time, Lion was the strongest and most feared of all the animals. He would catch other animals and eat them. But one morning while he was looking for his breakfast, he got caught in a hunter's trap.$$),
    ('10201', 1, $$Lion gave his loudest roar. He pulled and pulled to free himself from the trap. The trap got tighter and tighter around his leg every time he pulled. Lion grew tired and he felt more pain in his leg. Finally, he gave up.$$),
    ('10201', 2, $$Days went past as Lion lay baking in the sun. He was hungry and thirsty and there was nobody to save him. He became weaker and weaker. "I am going to die of hunger and thirst in this trap," he thought to himself.$$),
    ('10201', 3, $$One morning, Lion heard a sound coming from the nearby bushes. He listened and looked closer. He saw Warthog walking with his family, talking and laughing. The warthogs were going to the river to drink water and play in the mud before the sun got too hot.$$),
    ('10201', 4, $$"Warthog! Please help me! Warthog! " cried Lion. "Please set me free from this trap," he pleaded. "Never," said Warthog. "You are a cruel animal. You will eat me and my family for breakfast if I set you free. " "I promise I would never do such a bad thing. We will be friends if you can set me free," said Lion.$$),
    ('10201', 5, $$Warthog felt sorry for Lion. "I do not like seeing you in such pain, thirsty and dying from hunger," he said. So he pulled at the trap with his long strong tusks and released Lion. Warthog saved his new friend.$$),
    ('10201', 6, $$"Thank you for saving my life," said Lion. "I must go to my family now, good bye. " "Go well my friend," said Warthog. He was happy that Lion was his friend. "My family will never have to run from Lion again," he thought.$$),
    ('10201', 7, $$Lion walked away limping and weak. He was also very hungry. Then he saw Warthog's children playing in the mud. "Today is my lucky day," said Lion with his mouth watering.$$),
    ('10201', 8, $$"Warthog, my new friend," called Lion. "I have been caught in the trap for days without food. I am too weak to hunt. Please would you give one of your children to me for breakfast? " Warthog was shocked. "I saved you from the trap and now you want to eat my children? "$$),
    ('10201', 9, $$"I am very sorry my friend," said Lion, "but I am starving. I might be weak right now, but I am still stronger than you. " Lion opened his mouth and showed his strong teeth. "If you do not give me one of your children, I will take one for myself," he roared.$$),
    ('10201', 10, $$Warthog knew that he did not have the speed or the strength of Lion. He would never be able to protect his children in a fight. "All right," agreed Warthog. "I will give you one of my children. But first I want you to show me how you were caught in the trap. In case I have to save another lion from such a trap. "$$),
    ('10201', 11, $$Lion imagined the wonderful taste of young warthog in his mouth. He could hardly wait. He went back to the trap and put his foot inside, to show his friend how he was trapped.$$),
    ('10201', 12, $$"Ouch! " Lion roared. Warthog had closed the trap on Lion's foot. "Aha! I got you," said Warthog. "You will stay in that trap hungry and thirsty again. See if your strong teeth and sharp claws can help you now. "$$),
    ('10201', 13, $$"Run! Run! Run away! " Warthog's wife shouted to the children at the top of her voice. "Raise your tails when you are running so that your father can see you," she called. The babies ran as fast as they could through the bushes.$$),
    ('10201', 14, $$"Warthog please help me! " begged Lion again. He was in pain from hunter's trap. "I will do anything for you if you save me," he cried. "No way, liar! I will never believe you again," shouted Warthog. "I will also warn other animals not to save you because you are very sly. "$$),
    ('10201', 15, $$Warthog saw his children running in a row with their mother. Their tails were lifted up for him to see them. He rushed to his family and they all escaped safely. To this day, warthogs always run with their tails lifted up to see that everyone is safe.$$),
    ('10261', 0, $$Clouds are a big sign of rain.$$),
    ('10261', 1, $$It is very hot today. Why?$$),
    ('10261', 2, $$Clouds can hide the sun. I like clouds so much.$$),
    ('10261', 3, $$Is it raining out side? "Asked teacher Nabune. "$$),
    ('10261', 4, $$Is it windy?$$),
    ('10261', 5, $$Tell me more about weather.$$),
    ('10271', 0, $$Samba's dad bought him a new school shirt last market day.$$),
    ('10271', 1, $$Samba never misses school. He walks to school with his little sister.$$),
    ('10271', 2, $$Samba likes playing football after school. He wears his new shirt.$$),
    ('10271', 3, $$The shirt gets dirty. But Samba does not want to wash it!$$),
    ('10271', 4, $$On the field, Samba wants everyone to see his new shirt.$$),
    ('10271', 5, $$In the morning Samba goes to school with the dirty shirt. He sees the teacher waiting at the gate.$$),
    ('10271', 6, $$Samba dodges school that day and goes across the road to play football.$$),
    ('10271', 7, $$Unfortunately the new shirt gets torn. Now Samba is in trouble for dodging school and for tearing his new school shirt.$$),
    ('10427', 0, $$She had a big red belt round her waist.$$),
    ('10427', 1, $$In her hand, she carried a shiny little orange handbag.$$),
    ('10427', 2, $$She wore a pair of shiny orange high-heeled shoes.$$),
    ('10427', 3, $$She stopped and touched her long hair, which was held together in the middle with a hairpin.$$),
    ('10427', 4, $$As she fixed her hairpin, her handbag fell down. "Ouch," I said feeling bad for her.$$),
    ('10427', 5, $$The lady bent to pick up her handbag.$$),
    ('10427', 6, $$I saw long orange earrings as she cleaned the dust off her handbag.$$),
    ('10455', 0, $$Once upon a time in a big palace, there lived a king and his beautiful daughter, the princess.$$),
    ('10455', 1, $$Elephant lived in a house on one side of the palace. Chameleon lived on the other side.$$),
    ('10455', 2, $$At this time, there was a terrible drought across the land. The king had an idea and called his two neighbours to the palace.$$),
    ('10455', 3, $$The kind said to Elephant and Chameleon, "I want you to stomp on the ground with your feet until water comes out. " The king promised the princess in marriage to the one who succeeded.$$),
    ('10455', 4, $$Chameleon had no hope since he was very small. Elephant was extremely happy since he was so big and powerful. Elephant went to the field and started stomping on the ground.$$),
    ('10455', 5, $$A lot of dust came, but no water. Elephant stomped on the ground until water was almost coming out, but he was too tired. He gave Chameleon a chance to try.$$),
    ('10455', 6, $$Chameleon started stomping on the ground. After a short while, water came out. People could not believe their eyes!$$),
    ('10455', 7, $$So the King gave the beautiful princess to Chameleon. Elephant went home annoyed.$$),
    ('10460', 0, $$It happened one year that the rain didn't fall. The trees dried up and died. The rivers disappeared and the water evaporated. People and animals began dying from hunger and thirst.$$),
    ('10460', 1, $$Lion and Elephant as the chief animals got together to discuss the situation. Lion said, "We're going to end up dying from thirst. Let's call everyone together and discuss the idea of digging a well. " Elephant agreed and went off to spread the news to all the animals.$$),
    ('10460', 2, $$All the animals except Hare got together to discuss the situation. Lion said, "Look, my brothers and sisters, this year, the rain has not fallen. Everyone is dying from hunger and thirst. Let us now make a plan to dig a well so that we might all be able to drink from it. "$$),
    ('10460', 3, $$All the animals agreed and immediately grabbed hoes, shovels and started digging. They dug and dug. Finally they hit water. Lion said, "Why did Hare not come to dig this well? He most certainly will not drink from this water! "$$),
    ('10460', 4, $$Later Hare came and saw the well. He said, "Tipite, tipite at the well! " He heard nothing. So he went in, drank some water and splashed around for a while.$$),
    ('10460', 5, $$The next day, when the animals came they saw that their well was a big mess. The water was nothing but mud. They asked, "Who would do such a thing? " Someone said, "It must be Hare. When we were digging the well he was nowhere to be found. "$$),
    ('10460', 6, $$And so the animals decided to leave a guard at the well. They chose Baboon to keep an eye on things. Baboon was at the well when Hare came at night saying, "Tipite! Tipite! By the water! " Baboon replied, "Pitani! " So Hare came over and greeted Baboon, "I have come, my friend, and I bring that which the great ones like to eat! " Baboon replied, "Come, let's see what it is. "$$),
    ('10460', 7, $$Hare had some honey. He went over to Baboon, "Yes, my friend, try some of this! " Hare gave him the honey. Then he drew some water from the well and drank it. Just as Hare was leaving, Hyena arrived and saw him.$$),
    ('10460', 8, $$The next day, Hyena went and told all the animals that Hare had taken water from the well. So they chose Turtle to guard the well. Hare arrived at night, saying, "Tipite by the well! " When he didn't hear any reply he said: "I am Hare! I've come to drink water. "$$),
    ('10460', 9, $$When Turtle had arrived at the well earlier that night, she had hidden herself among the rocks. She looked just like another rock. As soon as Hare started to go into the water, Turtle grabbed Hare by the leg. Turtle didn't say a word, she just sat there holding on until the sun came up.$$),
    ('10460', 10, $$When the animals arrived, they saw that Turtle had captured Hare. They called the rest of the animals to decide what to do with Hare. When all the animals were assembled, Lion asked them, "What shall we do with this Hare? "$$),
    ('10460', 11, $$Turtle said, "Elephant should grab him with her trunk and beat him on the rocks. " All the other animals agreed. Then Hare said, "O Great Lion, you know that hares don't die if you hit them on rocks. Hare will only die if he is thrown into ash. " So Lion told Elephant to throw Hare into ash.$$),
    ('10460', 12, $$After Hare was completely covered with ash, Elephant picked him up and threw him. When Hare landed he made a big cloud of dust. The dust was everywhere.$$),
    ('10460', 13, $$When the dust settled, the animals looked around. Hare was gone! They realised that Hare had tricked them again.$$),
    ('10852', 0, $$Once upon a time, there lived a little bird in a warm, cozy nest. The little bird loved to sing every morning from its big tree with strong branches.$$),
    ('10852', 1, $$Every day when Little Bird looked up, she could see monkeys swinging high up in the tree. They danced and climbed on the branches. Little bird wished that she could swing like them high up in the tree and dance like them.$$),
    ('10852', 2, $$She wished and wished and wished, until one morning, she found that her wish had been granted. When she woke up, she was a Little Monkey! She ran up the tree and swung on the highest branches and chattered: oo-ooh a-aah o-ooh a-aah o-ooh a-aah Oh how happy she felt!$$),
    ('10852', 3, $$But one night, there was a big storm in the forest. Little Monkey tried to hide in a nest but - she was too big! She could not fit into a nest - she was a monkey, not a bird! She tried to hide with the other monkeys but they did not understand when she tried to talk to them; she was too chirpy! She sounded like a bird, so they chased her away. Little Bird became so sad. She got rained on and rained on, until she got a cold. If only she was a Little Bird again.$$),
    ('10852', 4, $$Luckily for Little Bird, the next day was better. She had turned into a Little Bird again. Oh, how joyful she now was! She sung all day long in her nest. Little Bird soon forgot all about her ordeal when she saw a squirrel running on the ground. The squirrel ran playfully with his friends and jumped around.$$),
    ('10852', 5, $$"Oh," wished Little Bird, "if only I too could run on the ground with my friends. " "Oh, how I want to be a squirrel. " Little Bird wished and wished and wished some more, until she was turned into a Little Squirrel! She ran on the ground in glee and chased the other squirrels.$$),
    ('10852', 6, $$But alas! What did she hear behind her? She turned just in time to see a big snake almost eat her! Oh, poor Little Squirrel. She ran as fast as she could to look for a place to hide. The snake followed her so fast. Little Squirrel tried to get into a hole, but it was already full of other squirrels. No-one wanted her there – they shut their door and shooed her away.$$),
    ('10852', 7, $$Little Squirrel ran and ran until her feet felt so sore and tired. How she wished she had wings to fly away. But she was not a bird - she was a squirrel! After running for so long, she found a big bush to hide in. She trembled as she hoped that the snake would not see her. The snake slithered and hiss-ssed as it came closer and closer. Little Squirrel tried to keep very, very still so that the snake would not see her. Suddenly, she heard something jump in front of her. Little Squirrel knew that she had been found out and she closed her eyes very tight and waited - to be eaten.$$),
    ('10852', 8, $$It was soo silent that she was sure that the snake had swallowed her and she was in the snake's stomach. She opened her eyes slowly, the left eye, then the right. When she looked up, she saw a hare running away. It was the hare that had jumped and frightened her so. The snake was now chasing hard after the hare. Little Squirrel stood up slowly, her little heart pounding in her chest. She was so glad that she was alive.$$),
    ('10852', 9, $$Little Squirrel promised that if she became a bird again, she would never, ever complain. She would be grateful because she could fly, and that she could fit in her nest. The next morning, when Little Squirrel woke up, she was a Little Bird again. She sang in her little nest and happily stayed content.$$),
    ('12412', 0, $$My name is Simo.$$),
    ('12412', 1, $$Meet my new friends.$$),
    ('12412', 2, $$Zizo, Lele, Sisa and Ayanda.$$),
    ('12412', 3, $$Zizo loves football.$$),
    ('12412', 4, $$Lele loves to swim.$$),
    ('12412', 5, $$Sisa loves to play hide and seek.$$),
    ('12412', 6, $$Ayanda loves reading.$$),
    ('12412', 7, $$I enjoy everything my friends love.$$),
    ('12412', 8, $$I will play football with Zizo.$$),
    ('12412', 9, $$Sometimes I swim with Lele.$$),
    ('12412', 10, $$Or even play hide and seek with Sisa.$$),
    ('12412', 11, $$Come on, make new friends and have fun.$$),
    ('12412', 12, $$Play football together.$$),
    ('12412', 13, $$Swim together.$$),
    ('12412', 14, $$Play hide and seek together.$$),
    ('12412', 15, $$Or even read together.$$),
    ('13306', 0, $$Khotso rides a donkey. His donkey is blue. Khotso and his donkey eat together.$$),
    ('13306', 1, $$Grandmother Thabo is cooking. She is cooking in a black pot. Grandmother Thabo and her cat eat together.$$),
    ('13306', 2, $$Neo's cow is as green as grass. The cow stands on Neo's foot. She drops her bucket of milk.$$),
    ('13306', 3, $$Ntate Phakane has a black horse. His horse is very strong. The horse pulls the plough all by itself.$$),
    ('13306', 4, $$Thabang drives his car. He travels with his dog. Thabang's dog poops in the car!$$),
    ('13306', 5, $$The blue donkey, the green cow, the black horse, and grandmother's cat got into Thabang's car. They started to sing. Who has the sweetest voice?$$),
    ('13527', 0, $$Sherry likes her school bag.$$),
    ('13527', 1, $$It is Sherry's birthday.$$),
    ('13527', 2, $$Sherry at the tax park.$$),
    ('13527', 3, $$Sherry with her friends.$$),
    ('13527', 4, $$Sherry at the market with her mum.$$),
    ('13527', 5, $$Ooh! It is time for food.$$),
    ('13527', 6, $$Sweet oranges.$$),
    ('13527', 7, $$But where is mother mother?$$),
    ('13527', 8, $$I went to buy a birthday gift for you.$$),
    ('13527', 9, $$Thank you mum!$$),
    ('13624', 0, $$Once upon a time all the animals lived together in the bush. The rooster was their chief.$$),
    ('13624', 1, $$Rooster told the animals that the comb on his head was made of fire. For this reason all the animals feared the rooster.$$),
    ('13624', 2, $$In those days, fire was made using a bow drill. One rainy day, Leopard's bow drill got wet. She could not make a fire to warm her family.$$),
    ('13624', 3, $$So Leopard sent her cubs to ask Rooster for fire from his comb.$$),
    ('13624', 4, $$Rooster was in a bad mood. He sent the cubs away without any fire. Leopard was upset when the cubs came back with nothing.$$),
    ('13624', 5, $$Late that night when Rooster was asleep, Leopard and cubs went to steal the fire from Rooster's comb. Leopard picked some dry grass outside Rooster's house.$$),
    ('13624', 6, $$She put the dry grass next to the sleeping Rooster's comb. But the grass did not catch fire. She carefully touched the comb. It was cold!$$),
    ('13624', 7, $$The cubs also touched the comb. There was no fire! The leopard family all started laughing.$$),
    ('13624', 8, $$The leopards' laughter woke Rooster and the chickens. Rooster turned his comb towards them, shouting, "You should run away. Aren't you afraid? "$$),
    ('13624', 9, $$Leopard replied, "We touched your comb and we know about your trick! We'll go back and tell the other animals. They will be angry with you. "$$),
    ('13624', 10, $$The chickens were afraid. They ran away and Rooster ran with them. The chickens left the bush and went to live with people.$$),
    ('13624', 11, $$Since that time, chickens have feared leopards and lived with people for protection.$$),
    ('13627', 0, $$Tom carries a tray of ripe bananas.$$),
    ('13627', 1, $$Tom goes to the market to sell bananas.$$),
    ('13627', 2, $$People at the market are buying fruit.$$),
    ('13627', 3, $$But no one is buying Tom's bananas. They prefer to buy fruit from women.$$),
    ('13627', 4, $$"In our community, only women sell fruit, " people say. "What kind of a man is this? " people ask.$$),
    ('13627', 5, $$But Tom does not give up. He calls, "Buy my bananas! Buy my sweet ripe bananas! "$$),
    ('13627', 6, $$One woman picks up a bunch of bananas from the tray. She looks at the bananas carefully.$$),
    ('13627', 7, $$The woman buys the bananas.$$),
    ('13627', 8, $$More people come to the stall. They buy Tom's bananas and eat them.$$),
    ('13627', 9, $$Soon, the tray is empty. Tom counts the money he earned.$$),
    ('13627', 10, $$Then Tom buys soap, sugar, and bread. He puts the things in his tray.$$),
    ('13627', 11, $$Tom balances the tray on his head and goes home.$$),
    ('13935', 0, $$Once upon a time there was a family with twelve children.$$),
    ('13935', 1, $$In the spring, the man planted some seeds in their garden. He said to his family, "I found these seeds and I don't know which plant they are from. " He warned them, "Don't eat the fruit until we know what it is. "$$),
    ('13935', 2, $$The seeds quickly grew into plants. The plants looked like pumpkin plants. Soon the round ripe fruit were ready for harvesting.$$),
    ('13935', 3, $$Just at this time, the father went away from his family, to work. The mother went to the market to look for food for her children.$$),
    ('13935', 4, $$The children were so hungry that they couldn't wait for their mother to return. The eldest child said, "Look, I'm sure those are pumpkins, let's pick some! " So they picked the plants. They cooked them, and ate until they were full.$$),
    ('13935', 5, $$All the children fell down, dead! When their mother came home, she found her children lying lifeless. She saw the pumpkin skins on a plate.$$),
    ('13935', 6, $$She called a dove and asked it to fly to her husband.$$),
    ('13935', 7, $$When the dove reached the place where the man worked, it sang this song to him: Tsi tsi etsia mumbo Tsio khulola Ondieki, tsi tsi Maondo ki yaraka, tsi tsi Kamalira abana, tsi tsi Ekhumi na babili, tsi tsi.$$),
    ('13935', 8, $$The man was worried when he heard the dove's song. He started the journey home and went as fast as he could.$$),
    ('13935', 9, $$On the way he stopped to ask the advice of a healer. The healer listened to the father's story, and then gave him a magic stick.$$),
    ('13935', 10, $$When the man arrived home, he touched each child with the magic stick. The children slowly came alive again.$$),
    ('13935', 11, $$After that day, the children never again ate pumpkins.$$),
    ('14088', 0, $$This is Mama's garden. It is big and beautiful. Mama plants many crops in it.$$),
    ('14088', 1, $$This is a mango tree Mama planted. The mangoes are ripe and look juicy. They make me salivate.$$),
    ('14088', 2, $$Mama and I visit Mama's garden to get maize for roasting. Sometimes, Mama goes to sell the maize at the market.$$),
    ('14088', 3, $$Mama's garden has big pumpkins and tomatoes. There is one giant pumpkin I like looking at.$$),
    ('14088', 4, $$The neighbour's cows are feeding on Mama's sweet potato vines. Mama will be so angry when she finds out.$$),
    ('14088', 5, $$Mama also plants sugarcane. My friends and I love to play hide and seek in the sugarcane.$$),
    ('14293', 0, $$This is Billy. He is the goat Jan was given by his father as a gift. Even though Billy is stubborn, Jan loves him very much. He always gives birth to healthy kids that Jan and his father sell.$$),
    ('14293', 1, $$Yesterday Billy went out of their compound with her too kids. Jan does not like this because the kids easily get stolen or be eaten by dogs.$$),
    ('14293', 2, $$Billy chewed the books containing all the homework Ann had done. Ann was angry that she was going to be punished by her teacher. She kicked Billy very had. This made Jan angry. He locked himself in his room to play with his toys.$$),
    ('14293', 3, $$Jan is afraid that his father will sell Billy for what he has done. However, Mr Tom, his father does not want to annoy his son by selling Billy. He has promised to wait until the kids are old enough so that he can give one to Jan.$$),
    ('14293', 4, $$We should be like Jan and Ann. We should take good care of our animals. Animals are important because they give us food and even protect us from bad people.$$),
    ('14309', 0, $$My friends and I were happy to have closed the school. We were to go for the Decemberholiday. I wanted to reach home to inform my parents that I had become the first position in my class during the exam that we had done.$$),
    ('14309', 1, $$I walked home smiling. I was just thinking how my father would feel having his only son being the top in a class of 57 pupils.$$),
    ('14309', 2, $$I reach home and find my sister Mimo. I told her my goodnews. "Dad and mom will be happy for you Uche, "She told me.$$),
    ('14309', 3, $$I woke up earlier the following day to start the day's duties. I went to feed the chicken and fetch the eggs with the help of Mimo.$$),
    ('14309', 4, $$We later walked to where we keep rabbits to feed them. Mimo and Kilonzi my friend helped in feeding while I made sure that the rabbits had enough water for the day.$$),
    ('14309', 5, $$That night after taking supper, our father told us good news that we were going to visit a Zoo on Saturday. We were happy since we have never been there before.$$),
    ('14309', 6, $$We woke up early to prepare for the journey. At 9: 00am we started our journey. Our walked together as we story tell. My mother was walking with Mimo and I with my dad.$$),
    ('14309', 7, $$We reached a point where we saw sweets, chocolate and snacks being sold. Dad bought us some for refreshment and we continued with our journey.$$),
    ('14309', 8, $$We reached the entrance and my heart was beating with joy for it was my first time to reach there. I saw many animals that I have only been seeing in books.$$),
    ('14309', 9, $$We got home happy but tired that evening after a long day of fun. Mother prepared meal for us which we took and retired to our beds.$$),
    ('14393', 0, $$Dan is a smart boy who likes reading, playing football and eating. He is a happy boy. His parents love him because he is obedient. Dan loves his parents too.$$),
    ('14393', 1, $$At school, Dan is very hardworking. He teaches others pupils what they were taught in school. He loves reading story books and by this he performs very well in English and Swahili. He is among the reading student in his class. His class teacher loves him and awards him with a pen and book. Dan is very happy.$$),
    ('14393', 2, $$After closing the school, Dan's father buys him a football because he is happy of his son. Dan is happy and he plays with his friends during the afternoon.$$),
    ('14393', 3, $$At home, Dan helps his parents home chores together with his sister. Their mother mother is very happy and promises to take them for a tour at the game park.$$),
    ('14393', 4, $$Dan's mum cooks him a nice meal. He loves chapati and chicken curry. He shares the food with his friends. Dan is generous and loves his friends.$$),
    ('14393', 5, $$On Sunday, Dan accompanies his parents to the church. He fears God and respects Him. He prays before sleeping and early in the morning before waking up.$$),
    ('14393', 6, $$Dan is taken to the game park by his parents together with his sister. At the game park he sees monkeys, giraffes, buffaloes, lions and rhinos. Dan is happier. There they drink juice and eat crisps. When they get back back home, he thanks his parents for making his day to be the one he will never forget.$$),
    ('14393', 7, $$His father also arranges a journey to go and greet Dan's grandparents. When in his grandparents home, Dan is cherishing his moments. He loves going to the riverside and observe the birds and the flow of the river water.$$),
    ('14393', 8, $$When they get back home, Dan is much happy and widely exposed. He now prepared for the next term of the school.$$),
    ('14393', 9, $$Dan is tells his classmates about his holiday times.$$),
    ('14514', 0, $$I colour in with my pencil crayons. .$$),
    ('14514', 1, $$I colour in tomatoes with a red pencil. .$$),
    ('14514', 2, $$I colour in oranges with an orange pencil. .$$),
    ('14514', 3, $$I colour in the sun with a yellow pencil. .$$),
    ('14514', 4, $$I colour in a frog with a green pencil. .$$),
    ('14514', 5, $$I colour in the night sky with a blue pencil. .$$),
    ('14514', 6, $$I colour in flowers with a pink pencil. .$$),
    ('14514', 7, $$I colour in a cat with a black pencil. .$$),
    ('14514', 8, $$I colour in the flag of Mozambique with many colours. .$$),
    ('14514', 9, $$.$$),
    ('14534', 0, $$Amelia wakes up and thinks, "Today is my first day of school. " .$$),
    ('14534', 1, $$"Carlos, what do I have to do? " asks Amelia. "I will tell you," replies Carlos. .$$),
    ('14534', 2, $$Carlos tells Amelia to wash her face. Amelia says, "I can wash my face. And then? " .$$),
    ('14534', 3, $$Carlos tells Amelia to brush her teeth. Amelia says, "I can brush my teeth. And then? " .$$),
    ('14534', 4, $$Carlos tells Amelia that she must eat. Amelia says, "I know how to eat. And then? " .$$),
    ('14534', 5, $$Carlos tells Amelia to put on her uniform. Amelia says, "I can put on my uniform. And then? " .$$),
    ('14534', 6, $$Carlos tells Amelia to pick up her bag. Amelia says, "I can pick up my bag. And then? " .$$),
    ('14534', 7, $$Carlos says, "You must go to school. " Amelia says, "I can go to school. And then? " .$$),
    ('14534', 8, $$Carlos says, "You must enter the classroom. "Amelia replies, "I can enter the classroom. And then? " .$$),
    ('14836', 0, $$When mother was younger, we visited her friends.$$),
    ('14836', 1, $$She took me to the market to buy vegetables.$$),
    ('14836', 2, $$She took my brother to town.$$),
    ('14836', 3, $$She taught me the names of plants.$$),
    ('14836', 4, $$When mother grew older, her back bent.$$),
    ('14836', 5, $$She stayed home more and talked to our neighbour's children.$$),
    ('14836', 6, $$She fell sick more often.$$),
    ('14836', 7, $$She walked with difficulty.$$),
    ('14836', 8, $$Her grandchildren went to visit her during holiday time.$$),
    ('14836', 9, $$Neighbours brought her milk from the shop.$$),
    ('14836', 10, $$When mother was younger, she was stronger.$$),
    ('14836', 11, $$Now, mother is older, she is weaker.$$),
    ('14917', 0, $$Manuel is very fond of trees. He writes what everyone says about the trees. "Trees are very important. Trees clean the air for us to breathe," says the teacher. "When a site is treeless, there is no rain and everything is dry. When everything is dry, it is difficult to grow food and people starve," says the farmer.$$),
    ('14917', 1, $$Grandpa says, "The tree casts a shadow, bears fruit and medicines. We make our homes with wood from the trees. " Mother says, "The tree roots hold the soil when there is rain and floods. The tree protects the houses and crops from strong winds. "$$),
    ('14917', 2, $$Manuel likes trees. He knows that a tree is home to many animals. One day, the teacher said, "Boys and girls, today we will make a drawing of a tree. Then we are going to write why the tree is important. "$$),
    ('14917', 3, $$Manuel is happy and draws a beautiful tree. He writes what the teacher, farmer grandfather, and mother had said about trees. Manuel has not forgotten anything. He likes trees a lot.$$),
    ('14917', 4, $$One day, Manuel sees Mr John Salimo cutting a tree. Manuel runs to tell his mother. Mother explains to Manuel, "The city needs wood, firewood and coal. People make money by selling these products. "$$),
    ('14917', 5, $$Manuel is sad. He is worried that people will use up the land's resources. If that happens, we will have no food. Manuel had an idea. He spoke to the teacher, "Teacher, they are cutting down all the trees. We need to have a meeting to teach parents that trees are important. "$$),
    ('14917', 6, $$The teacher agrees, "It is important to warn people. " In class, the teacher says, "Manuel wants to show parents why trees are important. " He asks the class to write a poem to recite at the meeting. On the day of the meeting, Manuel explains everything so well that the parents clap.$$),
    ('14917', 7, $$At the end of the meeting, the boys and girls of Manuel's class recite their poem. The poem says: Trees are our friends. Without the trees, we can not live. All parents listen to everything very carefully. Then parents decide, "Let's plant trees everywhere. "$$),
    ('14917', 8, $$The boys and girls of Manuel's class ask the teacher, "We want to plant trees. We do not want to live in a land without trees. " The teacher agrees, "We will work with the parents. Let's all plant trees! "$$),
    ('14930', 0, $$There once lived a man with a lot of livestock. He kept goats, camels, cows and donkeys. The man was married to a beautiful woman.$$),
    ('14930', 1, $$For a long time, the man and his wife did not have a baby. Then the woman gave birth to a beautiful girl. They named the baby Muurui. The man was happy and proud.$$),
    ('14930', 2, $$The woman was very busy. She left her baby alone in the hut and went to milk cows. The baby's gourd of milk was also in the hut.$$),
    ('14930', 3, $$When the baby was alone in the hut, she would wake up. She would drink all of the milk, and begin to cry. Her mother would run home to nurse her.$$),
    ('14930', 4, $$The woman always found the gourd empty. This was surprising! Who drank the milk?$$),
    ('14930', 5, $$The woman shared this problem with her husband. He decided to find out what happened to the milk.$$),
    ('14930', 6, $$The man hid in the hut when his wife went out. To his surprise, the baby got up and drank the milk! It was unbelievable.$$),
    ('14930', 7, $$The man told his wife what he saw and they decided to leave. They went at night, when the baby was asleep. They left their home.$$),
    ('14930', 8, $$And so, the magic baby was abandoned by her parents. They left her a goat, a cow and a camel. When Muurui awoke, she found the compound was quiet. She was all alone.$$),
    ('14930', 9, $$She felt angry. She killed the goat and the camel. Then she decided to hide inside the cow's stomach.$$),
    ('14930', 10, $$While Muurui's cow was grazing, a man passed by and saw it. He said, "I will slaughter this cow for beef. " He speared the cow.$$),
    ('14930', 11, $$As this man was skinning the cow, he heard a voice say, "Do not harm me, I am in the cow's stomach! "$$),
    ('14930', 12, $$Muurui then grabbed the man's head. He got such a fright that he ran away. He left the cow.$$),
    ('14930', 13, $$When the man got home, he slaughtered a fat ram. He cooked the meat and took it to the magic baby.$$),
    ('14930', 14, $$Muurui ate and was happy. The magic baby disappeared into the night.$$),
    ('14934', 0, $$I entered a dance contest with my friends. We put on our most beautiful dresses. I asked my mother, "Can I take that scarf? I like it very much. " Mother gave me the scarf. I was beautiful!$$),
    ('14934', 1, $$On the showground, there were many groups. All the girls wore colourful dresses. There was lively music. It made you want to dance. Everyone was very cheerful.$$),
    ('14934', 2, $$Mothers, grandmothers and aunts had made food that smells great. It made us feel hungry! In the contest, there were many prizes for all the groups that danced. All the groups danced very well.$$),
    ('14934', 3, $$The group of the oldest girls and boys won the contest. I said to my friends, "Our group was the best! We were beautiful and danced very well. We should have won. "$$),
    ('14934', 4, $$Farida heard me and was upset. She was in another group. She thought they had danced better. We started arguing. She yanked my head scarf and ran away with it.$$),
    ('14934', 5, $$It was the scarf that I borrowed from mother. I started to cry. My friends ran after Farida and brought the scarf back. I was very happy.$$),
    ('14934', 6, $$I forgot to be angry with Farida. The music was lively and cheerful. My friends and I did not stop dancing. It was such a fun day.$$),
    ('14934', 7, $$The next day early in the morning, I went to the well to fetch water. Farida also went early to the well to fetch water. We spoke of how all the groups were beautiful and how the dances were lively.$$),
    ('14934', 8, $$Both of us think that the dance contest should have lasted all weekend. We had already forgotten our anger. We were, again, good friends.$$),
    ('14951', 0, $$Tick-tock, tick-tock. It's the sound of my father's sewing machine. Even with the tick-tock, tick-tock, my father hears us when we arrive from school. "David, John, come here! " he calls.$$),
    ('14951', 1, $$"John, sit down beside me," says father. "My son, come and learn to be a tailor. " John sits beside his father and learns. But my brother is sad. In the evening, John says, "I do not want to be tailor. I want to be a teacher. I like to teach. "$$),
    ('14951', 2, $$Father replies that our grandfather and great-grandfather were tailors. Now he is a tailor. "Then it will be the turn of John. It's our family that makes clothes for the villagers, " says father. John already knows how to take measurements, cut cloth and sew. But he wants to be a teacher.$$),
    ('14951', 3, $$During the weekend, John helps boys and girls who have difficulties at school. John's classroom is under a large cashew tree. The boys and girls agree that John can explain very well.$$),
    ('14951', 4, $$When my teacher tells us about the professions, she says, "All professions are important. The farmers, artists, nurses, truckers, police officers, carpenters, pastors, tailors and teachers are all important! "$$),
    ('14951', 5, $$I draw a tailor and a teacher. I show it to my friends, and tell them, "I will give this picture to my brother! " I take home the drawing. My brother John is very fond of my drawing. He hangs the drawing on the wall. As we return from school, the sewing machine of our father makes the sound, "Tick-tock, tick-tock. "$$),
    ('14951', 6, $$My father has a big bandage on his finger. He is upset. "I broke my finger and it hurts so much that I cannot work! I have school uniforms to make," says father. "We will help you! " says John. I cannot sew, but John says to me, "I'll teach you, David! " Father looks at us and manages to smile.$$),
    ('14951', 7, $$I am pleased, "We completed the first uniform! " Father thinks John is a good tailor and a good teacher. "One day you'll have a classroom and many students! " says father. "Dad, John already has a classroom. It's under the cashew tree! He teaches during the weekend," I tell father.$$),
    ('14951', 8, $$Our father went to the hospital. His finger is still not good. When I introduce my brother to my friends, I say, "This is my brother! He's a good tailor. He helps our father after school. He will be the best teacher in Mozambique! "$$),
    ('14952', 0, $$Alfredo likes drawing. Since he was little, Alfredo made drawings on the floor. He also made clay models. Alfredo's mother always says, "Alfredo, you are an artist! "$$),
    ('14952', 1, $$In the first year of school, Alfredo wanted to learn to read and to write. The other boys replied, "Alfredo, we will help you. "$$),
    ('14952', 2, $$In the second year of school, Alfredo was pleased. He knew how to read and to write. He thought, "I can already tell stories with pictures. I can draw. I want to tell many stories with drawings! "$$),
    ('14952', 3, $$One day, Alfredo showed his notebook to the teacher. He told a story with pictures. The teacher looked at Alfredo's notebook. She saw many beautiful drawings and said, "Alfredo, your notebook is very nice! "$$),
    ('14952', 4, $$Alfredo was pleased. He thought, "I know how to draw. I want to tell many stories with drawings! " The teacher told the class, "Today we will all tell a story with pictures. " Alfredo begins to draw quickly. "I'll tell you about the day of my birthday! " he says.$$),
    ('14952', 5, $$The teacher calls, "Come, see all of Alfredo's drawings. They are so nice! " All the boys and girls agree, "Alfredo can draw very well! Alfredo knows how to tell beautiful stories! "$$),
    ('14952', 6, $$All the boys and girls ask, "Alfredo, can you draw for us? Alfredo, tell more stories with pictures! " The teacher says, "Alfredo, you have to teach us how to draw. We all want to learn. "$$),
    ('14952', 7, $$Alfredo is happy. He thinks, "Now I will be the drawing teacher for all the boys and girls. Even the teacher wants to learn to draw like me! " The teacher says, "Alfredo, now you just need to learn to write better, without mistakes. You can be a great writer! "$$),
    ('14952', 8, $$A story by Alfredo is chosen to go in a magazine. The teacher and the director show the magazine to all the students. The teacher says, "Alfredo is now a writer! "$$),
    ('14953', 0, $$"Carlos, don't give corn kernels to the dog! " says Maria. "But the dog is hungry," replies Carlos. "Comes with me to feed the animals. They are all hungry," says Maria.$$),
    ('14953', 1, $$"Since you have corn kernels in your hand, let's start with the poultry," says Maria. Carlos throws the corn to the chickens. The chicks squeal, "Piupiu. " The chickens cluck, "Couck. Couck. "$$),
    ('14953', 2, $$"Now let's give sorghum to the pigeons," says Maria. Carlos throws sorghum to the pigeons. The pigeons land on the floor. The pigeons coo, "Curru. Curru," while they eat.$$),
    ('14953', 3, $$"Maria, we forgot the dog. He is hungry and has not eaten, " says Carlos. "What are we going to give the dog? " he asks. The dog barks, "Whaf. Whaf. " He seems to be saying, "I'm hungry. "$$),
    ('14953', 4, $$The goats bleat, "Meee. Meee. " They seem to greet Carlos and Maria. "Now can we go and feed the rabbits? " asks Carlos. "Let's go," replies Maria. "Do you know what rabbits eat? "$$),
    ('14953', 5, $$"I know," answers Carlos, "let's give them some green leaves. At school I learned that they like carrots. " "Well done! Rabbits also need water," says Maria. Carlos fills the bowl of water for the rabbits.$$),
    ('14953', 6, $$"Maria, we forgot the dog. He is hungry and has not eaten, " says Carlos. "What are we going to give the dog? " he asks. The dog barks, "Whaf. Whaf. " He seems to be saying, "I'm hungry. "$$),
    ('14953', 7, $$Maria and Carlos go to fetch bones from the kitchen. "Whaf. Whaf," barks the dog, wagging his tail happily. Maria opens the pantry door. Two rats jump out and run away.$$),
    ('14953', 8, $$Maria cries, "The rats gnawed bags of peanuts. " "Rats eat peanuts? " asks Carlos. Mary replies, "They eat and chew everything. Where is the cat? " "Miauuuu," says Mia the cat, as she chases after the rats.$$),
    ('15055', 0, $$The wind roars. It roars past our home.$$),
    ('15055', 1, $$The wind is powerful. It tears my kite from my hand.$$),
    ('15055', 2, $$I run after my kite. The wind blows me away from the kite!$$),
    ('15055', 3, $$The wind becomes a tornado. It carries my kite higher and higher.$$),
    ('15055', 4, $$The tornado swallows me up! I see nothing, I touch nothing.$$),
    ('15055', 5, $$Where is my kite now? Perhaps it is caught in a tree.$$),
    ('15055', 6, $$Perhaps my kite is still flying in the sky.$$),
    ('15055', 7, $$The wind finally dies down. I am still spinning.$$),
    ('15055', 8, $$When I stop spinning I look around. Where did the wind go?$$),
    ('15055', 9, $$I cannot see my kite anywhere. I cannot hear the wind anymore.$$),
    ('15055', 10, $$Perhaps tomorrow I will find my kite.$$),
    ('15055', 11, $$Now, I must go home, before the wind starts to roar again.$$),
    ('15093', 0, $$Everyone knows that elephants have long noses.$$),
    ('15093', 1, $$But a long time ago, the elephant's nose was short and fat.$$),
    ('15093', 2, $$A baby elephant was born. She was very curious. She had a question for every animal.$$),
    ('15093', 3, $$She was curious about Giraffe. "Why do you have a long neck? " she asked.$$),
    ('15093', 4, $$She was curious about Rhino. "Why does your horn have a sharp point? " she asked.$$),
    ('15093', 5, $$She was very curious about Crocodile. "What do crocodiles eat for dinner? " she asked.$$),
    ('15093', 6, $$Clever Crow quickly said, "Follow me to the river. There you will see what crocodiles eat for dinner. "$$),
    ('15093', 7, $$So Baby Elephant followed Crow to the river.$$),
    ('15093', 8, $$She pushed through the reeds and stood on the bank. She looked into the water. Where was Crocodile?$$),
    ('15093', 9, $$"Hello," said a stone near the river bank. "Hello," said Baby Elephant. "Can you tell me what crocodiles eat for dinner? " she asked.$$),
    ('15093', 10, $$"Come closer and I will tell you," said the stone. Baby Elephant bent down. "Come closer," said the stone. Baby Elephant bent down lower.$$),
    ('15093', 11, $$Suddenly! Snap! Crocodile grabbed Baby Elephant's nose in his jaws.$$),
    ('15093', 12, $$Baby Elephant sat back on her strong legs and pulled. And pulled, and pulled. But Crocodile did not let go of her nose.$$),
    ('15093', 13, $$Baby Elephant's nose stretched and stretched. And stretched. Until she fell over. "Dufff! "$$),
    ('15093', 14, $$Baby Elephant's short nose had stretched into a long nose.$$),
    ('15093', 15, $$Her nose was so long she could pick fruit from high branches. And to this day, all elephants have long and useful trunks.$$),
    ('15394', 0, $$Once upon a time, there live a very lazy girl called Cheptoo in Kimongo village. She was so lazy that she could not do anything.$$),
    ('15394', 1, $$Whenever her mother sends her to the river to fetch water, she always walk slowly and slowly and return home after a long long time.$$),
    ('15394', 2, $$One day her mother called her "Cheptoo where are you? " she emerges from the smoky filled house and reply "yes mum" her mother told her "make sure you swept the house and wash the utensils, am going to the Shamba. "$$),
    ('15394', 3, $$As soon as her mother left she began to sweep the house, she swept and swept that she took a very long long time doing so. Her mother arrive from the shamba and began calling her "Cheptoo? " she replied in a low tone "ii.i. Yoo! " after a long hesitation, tears started rolling down her eyes because she had not washed the utensils as she was told to do so.$$),
    ('15394', 4, $$Her mother get so hungry and she began to beat Cheptoo. She began crying " wuuii! Wuuii! Wuuii, forgi. Iive m. Ee" she cried and cried all day long while blinking like an owl, she was punished to do a lot of work that day.$$),
    ('15394', 5, $$From that day Cheptoo did not become lazy again, she automatically change after being beaten thoroughly by her mother.$$),
    ('15410', 0, $$My name is John.$$),
    ('15410', 1, $$I have an older brother called Ken. Ken loves me and I love him too.$$),
    ('15410', 2, $$We walk to school together in the morning.$$),
    ('15410', 3, $$When the bell rings for break time, Ken helps me to put on my games uniform.$$),
    ('15410', 4, $$Often I play with Ken and his friends during break. When the bell rings at the end of the day, we hurry home.$$),
    ('15410', 5, $$After we reach home, we go to swim in the river.$$),
    ('15410', 6, $$At bedtime Ken reminds me how to brush my teeth.$$),
    ('15410', 7, $$During the weekend, we go to play football in the field.$$),
    ('15410', 8, $$I love my brother very much.$$),
    ('15410', 9, $$My mother loves watching her children play football.$$),
    ('15575', 0, $$I enjoy skipping with my friend.$$),
    ('15575', 1, $$I enjoy writing letters on the board.$$),
    ('15575', 2, $$I enjoy reading books with pictures.$$),
    ('15575', 3, $$I enjoy eating different fruit.$$),
    ('15575', 4, $$I enjoy helping at home.$$),
    ('15575', 5, $$I enjoy listening to my mother's stories.$$),
    ('15575', 6, $$I enjoy sleeping on a big bed.$$),
    ('15575', 7, $$I enjoy doing these things. What do you enjoy doing?$$),
    ('15750', 0, $$Now Jesus was praying in a certain place. When he stopped, one of his disciples said to him, "Lord, teach us to pray, just as John taught his disciples. " So he said to them, "When you pray, say: Father, may your name be honored; may your kingdom come. Give us each day our daily bread, and forgive us our sins, for we also forgive everyone who sins against us. And do not lead us into temptation. "$$),
    ('15750', 1, $$Then he said to them, "Suppose one of you has a friend, and you go to him at midnight and say to him, 'Friend, lend me three loaves of bread, because a friend of mine has stopped here while on a journey, and I have nothing to set before him. '. "$$),
    ('15750', 2, $$Then he will reply from inside, 'Do not bother me. The door is already shut, and my children and I are in bed. I cannot get up and give you anything. '.$$),
    ('15750', 3, $$I tell you, even though the man inside will not get up and give him anything because he is his friend, yet because of the first man's sheer persistence he will get up and give him whatever he needs.$$),
    ('15750', 4, $$"So I tell you: Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened for you. For everyone who asks receives, and the one who seeks finds, and to the one who knocks, the door will be opened. "$$),
    ('15838', 0, $$The land of a certain rich man produced an abundant crop.$$),
    ('15838', 1, $$The rich man thought to himself, "What should I do, for I have nowhere to store my crops? "$$),
    ('15838', 2, $$Then he said, "I will do this: I will tear down my barns and build bigger ones, and there I will store all my grain and my goods. "$$),
    ('15838', 3, $$And I will say to myself, "You have plenty of goods stored up for many years; relax, eat, drink, celebrate! "$$),
    ('15838', 4, $$But God said to him, "You fool! This very night your life will be demanded back from you, but who will get what you have prepared for yourself? "$$),
    ('15838', 5, $$So it is with the one who stores up riches for himself, but is not rich toward God.$$),
    ('15838', 6, $$After telling this story, Jesus said to his disciples: Therefore I tell you, do not worry about your life, what you will eat, or about your body, what you will wear.$$),
    ('15838', 7, $$For there is more to life than food, and more to the body than clothing.$$),
    ('15838', 8, $$Consider the ravens: They do not sow or reap, they have no storeroom or barn, yet God feeds them. How much more valuable are you than the birds!$$),
    ('15838', 9, $$And which of you by worrying can add an hour to his life? So if you cannot do such a very little thing as this, why do you worry about the rest?$$),
    ('15838', 10, $$Consider how the flowers grow; they do not work or spin. Yet I tell you, not even Solomon in all his glory was clothed like one of these! And if this is how God clothes the wild grass, which is here today and tomorrow is tossed into the fire to heat the oven, how much more will he clothe you, you people of little faith!$$),
    ('15838', 11, $$So do not be overly concerned about what you will eat and what you will drink, and do not worry about such things. For all the nations of the world pursue these things, and your Father knows that you need them.$$),
    ('15838', 12, $$Instead, pursue his kingdom, and these things will be given to you as well. Luke 12: 16-31.$$),
    ('15972', 0, $$Neo takes her pig for a ride on her bicycle.$$),
    ('15972', 1, $$She hits a stone in the road. The pig falls down. It cries. It says, "Hooeeeee, hooeeeee! "$$),
    ('15972', 2, $$Tsotang finds it. He says, "Haaiee, who does this pig belong to? "$$),
    ('15972', 3, $$Tsotang chases it, until he catches it.$$),
    ('15972', 4, $$He takes the pig to the chief. The chief tells him to look after it.$$),
    ('15972', 5, $$Neo passes by on the path. She hears the pig grunting, "Hmmm, hmmm, hmmm! "$$),
    ('15972', 6, $$She goes in. She is happy to see her pig.$$),
    ('15972', 7, $$Neo says to her pig, "Come, let's go home. We will not ride the bicycle again. "$$),
    ('16120', 0, $$This is Norah. Norah's doll is called Sellah.$$),
    ('16120', 1, $$Norah loves Sellah very much. She plays and sleeps with Sellah every night.$$),
    ('16120', 2, $$One day, Norah was very worried because she could not find Sellah.$$),
    ('16120', 3, $$Norah's mother had washed Sellah.$$),
    ('16120', 4, $$Norah went to her mother crying, "I can't find Sellah. "$$),
    ('16120', 5, $$Before Norah slept, her mother brought Sellah to her.$$),
    ('16120', 6, $$Norah jumped out of bed and danced with Sellah.$$),
    ('16120', 7, $$Norah hugged her mother and thanked her for cleaning Sellah.$$),
    ('16193', 0, $$There is a woman called Mrs Rubandama. She lives in Kakuuto village.$$),
    ('16193', 1, $$She has a sewing machine. She uses it to make clothes of different fashions.$$),
    ('16193', 2, $$She makes different costumes.$$),
    ('16193', 3, $$She makes school uniforms of grey and white for boys and girls.$$),
    ('16193', 4, $$She makes blue uniforms and many other colours.$$),
    ('16193', 5, $$She makes aprons for chefs.$$),
    ('16193', 6, $$Her husband helps to measure and cut patterns.$$),
    ('16193', 7, $$She makes casual clothes for outings.$$),
    ('16193', 8, $$She makes tops, skirts and shorts.$$),
    ('16193', 9, $$She also makes beautiful bridal clothes.$$),
    ('16245', 0, $$A sower went out to sow his seed.$$),
    ('16245', 1, $$And as he sowed, some fell along the path and was trampled on, and the wild birds devoured it.$$),
    ('16245', 2, $$Other seed fell on rock, and when it came up, it withered because it had no moisture.$$),
    ('16245', 3, $$Other seed fell among the thorns, and they grew up with it and choked it.$$),
    ('16245', 4, $$But other seed fell on good soil and grew, and it produced a hundred times as much grain. "As he said this, he called out, "The one who has ears to hear had better listen!$$),
    ('16245', 5, $$Then his disciples asked him what this parable meant. He said, "You have been given the opportunity to know the secrets of the kingdom of God, but for others they are in parables, so that although they see they may not see, and although they hear they may not understand. "$$),
    ('16245', 6, $$Now the parable means this: The seed is the word of God. Those along the path are the ones who have heard; then the devil comes and takes away the word from their hearts, so that they may not believe and be saved. Those on the rock are the ones who receive the word with joy when they hear it, but they have no root. They believe for a while, but in a time of testing fall away.$$),
    ('16245', 7, $$As for the seed that fell among thorns, these are the ones who hear, but as they go on their way they are choked by the worries and riches and pleasures of life, and their fruit does not mature.$$),
    ('16245', 8, $$But as for the seed that landed on good soil, these are the ones who, after hearing the word, cling to it with an honest and good heart, and bear fruit with steadfast endurance.$$),
    ('16483', 0, $$Sidney is a little girl who lives with her mother. Although she was small she had a big dream. She always wanted to go to the circus since she first read a story about circus animals.$$),
    ('16483', 1, $$One night after Sidney's mother kissed her goodnight she told her that they will be going to the circus the following day. Extremely excited Sidney hugged her mom and went right to sleep.$$),
    ('16483', 2, $$In Sidney's dream she came across a beautiful tent and immediately assumed it was a circus tent. "Yes, it sure is," she said as there was a clown standing right next to the entrance.$$),
    ('16483', 3, $$It had such pretty golden brown hair with thick brown mane. It was completely tame with no intention to harm anyone. "Oh what a big lion," she shouted.$$),
    ('16483', 4, $$Sidney then entered the colourful tent and continue being amazed. She saw four more wild animals, this time they were quite small. They jumped in the air and did a few awesome tricks. "Oh what small monkeys," she whispered.$$),
    ('16483', 5, $$What Sidney saw next made her laugh and laugh and laugh. An animal that is usually in water, were dancing and clapping its flippers. Not only was it dancing but balancing a purple ball with its nose. "Oh what a big seal," she shouted.$$),
    ('16483', 6, $$An animal with grey leather skin gave a trumpet and made the whole crowd cheer of joy. It climbed upon a little stepping stool and started dancing. With its trunk it balanced a big ball while standing on only its hind legs. "Oh what a big elephant," she shouted.$$),
    ('16483', 7, $$A tall man with big shoes made the whole crowd laugh with his jokes. He tied balloons in animal shapes for all the children. "Oh what a funny clown," she shouted.$$),
    ('16483', 8, $$One, two, three, four bears were handing out balloons and flowers for each person as a keepsake for their attendance at the circus. "Oh what small bears they were," she said.$$),
    ('16483', 9, $$Suddenly Sidney's mom woke her up to get dressed and eat breakfast before their journey to the circus. When they arrived at the tent, Sidney saw a wild animal standing right next to the entrance. "Oh what a big lion," she shouted. It was exactly like her dream.$$),
    ('16510', 0, $$It is hot sunny Saturday morning on the farm. Maya, Duksie and Doobie are helping Mama K in her vegetable garden. The children work all morning. They dig compost into the soil. They weed and water. Then they harvest what is ripe and ready. Today each of the children will take home freshly picked strawberries, spinach and carrots.$$),
    ('16510', 1, $$Mama K always gives the children a treat for helping her. Sometimes its cake or chocolate, or she buys long sweets that look like snakes. Sometimes it's apples, pears or oranges. Mama K has only one rule. "Share it fair! " The children know they must share the treats equally, so they all get the same amount.$$),
    ('16510', 2, $$Today Mama K has baked a round strawberry cake with pink icing and berries from her garden. The children wait on the grass for their treat. "Here you go! " smiles Mama K. "But remember the rule. Everyone must get the same. Share it fair! Don't fight! "$$),
    ('16510', 3, $$Maya has the first turn to share the cake. She uses the knife to trace lines in the icing. The others watch her. She does not cut the cake yet. The others must first agree if her way is fair. "I think I will make two cuts down like this. Now we have three slices, all the same! " Maya shows them.$$),
    ('16510', 4, $$"No way! " says Duksie, "the one in the middle is much too big! " Doobie also shakes his head. Maya laughs and shrugs and tells Duksie to try.$$),
    ('16510', 5, $$"Here! Pass me the knife, I'll do it. Easy peasy! " chants Duksie. First she rubs out Maya's pattern in the icing and licks her fingers.$$),
    ('16510', 6, $$Then she makes one cut across and one down. "Look, I made my three slices! " "That's not fair! " shout Maya and Doobie together.$$),
    ('16510', 7, $$"Share it fair! The pieces must be the same size and shape," adds Doobie. "Why don't you try Doobie, Smarty Pants? " smirks Duksie. "I bet you can't do it! "$$),
    ('16510', 8, $$"I wish the cake was a square or a rectangle, and then it would be easy! " says Doobie thoughtfully. "Or, if there were four of us to share the round cake that would also be easy," says Maya.$$),
    ('16510', 9, $$And then! A picture comes into Doobie's head. He sees the sparkling silver badge at the front of his father's big red truck. On Sundays he helps his dad to wash the truck, and to polish the shiny badge. "I've got it! I've got it! I know how to do it," yells Doobie.$$),
    ('16510', 10, $$First he uses a knife to smooth Duksie's lines in the icing. Then he traces three lines on the cake. It looks just like the badge on his dad's truck, with three equal parts.$$),
    ('16510', 11, $$"You are full of surprises, Doobie," says Duksie sweetly. "How did you work it out? " Maya asks. Doobie smiles to himself. For now it his secret. Later, he will tell his dad.$$),
    ('16510', 12, $$Just then Mama K comes out of her house. She is carrying a tray with three glasses of cold strawberry juice. "Look Mama K! Doobie found the way to cut the cake into three equal pieces," Maya tells her. "Well done Doobie, three equal slices! You shared fairly, I'm proud of you all. Now cut the cake and drink your juice. It's time to go home. I will give you plates to take your pieces of cake. "$$),
    ('16510', 13, $$Maya cuts along Doobie's lines to make three equal slices. Just for fun, the children stack the slices on top of each other to check that they are the same size. Yes they are!$$),
    ('16510', 14, $$Doobie's dad arrives to pick up the children, and Doobie runs off to meet him. He can't wait to tell his dad how the badge on the truck helped him to solve a very tricky problem!$$),
    ('16631', 0, $$I use my feet to run, jump, and kick.$$),
    ('16631', 1, $$I use my hands to eat, work, and hug.$$),
    ('16631', 2, $$But the head is more important than feet or hands.$$),
    ('16631', 3, $$The head has the eyes. I see with my eyes.$$),
    ('16631', 4, $$The head has the nose. I smell with my nose.$$),
    ('16631', 5, $$The head has the ears. I hear with my ears.$$),
    ('16631', 6, $$The head has the tongue. I taste salty and sweet.$$),
    ('16631', 7, $$The head has the mouth. I speak with my mouth.$$),
    ('16631', 8, $$The head controls the whole body!$$),
    ('17648', 0, $$The rat king was very proud. "The rats are the most wonderful animals in the world," he said. All the other rats agreed with him. "You're right," they all said. "We are the most wonderful animals in the world. "$$),
    ('17648', 1, $$"I'm the most wonderful king in the world," said the rat king. "It's true! You are the most wonderful king in the world," shouted all the other rats.$$),
    ('17648', 2, $$"My son is the most wonderful prince in the world," said the rat king. "We agree! Your son is the most wonderful prince in the world," agreed all the other rats.$$),
    ('17648', 3, $$"We must find a wife for my son," the rat king said to his elders. "No other animal is as wonderful as the rat. My son must marry the best girl in the world. Where can we find her? "$$),
    ('17648', 4, $$The elders thought for a long time. Then one of them said, "There is one person who is greater than us. " "Who is that? " asked the rat king. "Our Creator," the elder said. "You're right," the rat king said. "Our Creator is greater than us. Go and ask our Creator for his daughter. "$$),
    ('17648', 5, $$The elders of the rats went up to the sky to see their Creator. "Please," they said. "Our prince, the son of the rat king, is the most wonderful animal in the world. Will you give us your daughter to be his wife? "$$),
    ('17648', 6, $$The Creator smiled. "If your prince is really the most wonderful animal in the world, then he's too good for my daughter. He must marry someone greater than her," said the Creator. "Who? " asked the rats. "Fog is greater than me," said the Creator. "Fog comes into the sky and covers me. I can't escape from him. I can't send him away. Ask the fog for his daughter. "$$),
    ('17648', 7, $$The elders went back to their king. "The Creator is always right," the rat king said. "The fog is greater. Go and ask the fog for his daughter. "$$),
    ('17648', 8, $$So the elders went to find Fog. They said, "Our prince is the greatest animal in the world, and he wants to marry your daughter. " "Tell me about him," said Fog. "He's clever and handsome," the elder began. "Stop! " said the fog. "He's too good for my daughter. He must marry someone greater than me. "$$),
    ('17648', 9, $$"Who is greater than the fog? " the elders asked. "Wind is greater than me," said the fog. "She blows me away. I can't stand against the wind. Ask Wind for her daughter. "$$),
    ('17648', 10, $$The elders went back to the rat king. "Fog is right," said the rat king. "Wind is greater than him. Go and ask Wind for her daughter. "$$),
    ('17648', 11, $$The elders went to find the wind. "Great Wind," they said. "We come from the rat king. He is the greatest king in the world and he wants your daughter to marry his son. " "Is he really the greatest king in the world? " asked Wind. "He's too good for me. Your prince must find someone greater," she said.$$),
    ('17648', 12, $$"Who is greater than the wind? " the elders asked. "Mountain is greater than me," answered Wind. "I push against him and blow on him, but he never moves. Go and ask Mountain for his daughter. " The elders went back to their king. "Yes! " he cried. "Wind is right. Go and speak to the mountain. "$$),
    ('17648', 13, $$So the elders went and spoke to the mountain. "Is your prince really so great and wonderful? " asked Mountain. "He is too good for my daughter. He must marry someone better than her. " "Who? Who? " asked the elders. "The bush rat is greater than me," the mountain said. "He makes holes inside me and I can't stop him. "$$),
    ('17648', 14, $$The elders went back to their king. The rat king said, "The bush rat is my cousin! His daughter will be a very good wife for my son. "$$),
    ('17648', 15, $$So the rat prince married the bush rat's daughter. They lived happily for many years.$$),
    ('18240', 0, $$There was a boy named Mike. Mike was six years old. Mike was crying because he couldn't go for Fred's birthday party without his shoes.$$),
    ('18240', 1, $$Mike's mum shouted at him for misplacing his new shoes and said that he wouldn't leave unless he found his shoes. He searched and searched but only found the two left legs of different shoes.$$),
    ('18240', 2, $$Mike saw a floating man and asked who he was. "I am a genie" he said "Can I get a wish then? " Mike asked "Yes, but be careful what you wish for" He warned. Mike wished for two left legs so that he could wear the shoes and go for the party.$$),
    ('18240', 3, $$The genie granted him his wish and he was able to wear his shoes. Mike thanked the genie and got up but he found out that he could not walk with two left feet. Mike begged the genie to change it back but the genie refused and flew away. Mike missed his party. When his mum found out what happened, she cried because she had just found the right legs of his shoes. Mike could not walk again. Mike learnt his lesson. MORAL LESSON: Be careful what you wish for and always be patient.$$),
    ('18420', 0, $$There was Little Goat and Little Leopard. They became friends.$$),
    ('18420', 1, $$They went to a field together to play.$$),
    ('18420', 2, $$They returned home very late.$$),
    ('18420', 3, $$Little Goat said to his mama, "I met a beautiful friend. I am so happy. We will meet again tomorrow. "$$),
    ('18420', 4, $$Mama Goat answered, "Oh my child. I am glad you are back safely. He is not our friend. Do not meet him tomorrow. "$$),
    ('18420', 5, $$At the same time, Little Leopard told his mother, "I met a beautiful friend. I am happy. We will meet tomorrow. "$$),
    ('18420', 6, $$Mama Leopard answered, "Oh my son, I am sorry you did not eat Little Goat. When you meet him tomorrow, kill him and eat him. "$$),
    ('18420', 7, $$The next day, Little Leopard went to the Little Goat's village.$$),
    ('18420', 8, $$Little Goat was not outside. He was hiding inside with his mother.$$),
    ('18420', 9, $$Little Leopard shouted, "Let us go to the field to play. "$$),
    ('18420', 10, $$Little Goat said, "We are not friends anymore. I listen to my mama. Good children listen to their mamas. "$$),
    ('18420', 11, $$Little Leopard was sad. He went back to his mama.$$),
    ('18773', 0, $$Two thieves wanted to steal maize from a farmer's garden one night. They did know about one another.$$),
    ('18773', 1, $$The first thief came and harvested a sack of maize.$$),
    ('18773', 2, $$The second thief entered the farmer's garden, leaving his bicycle outside.$$),
    ('18773', 3, $$The two thieves bumped into one another in the maize field. They both cried out, "Who are you? "$$),
    ('18773', 4, $$They both got a fright and ran away in opposite directions.$$),
    ('18773', 5, $$The first thief left behind his bag of maize.$$),
    ('18773', 6, $$The second thief left behind his bicycle.$$),
    ('18773', 7, $$When the farmer came he used the bicycle to carry the sack of maize.$$),
    ('1880', 0, $$A long time ago, three girls went out to collect wood.$$),
    ('1880', 1, $$It was a hot day so they went down to the river to swim. They played and splashed and swam in the water.$$),
    ('1880', 2, $$Suddenly, they realised that it was late. They hurried back to the village.$$),
    ('1880', 3, $$When they were nearly home, Nozibele put her hand to her neck. She had forgotten her necklace! "Please come back with me! " she begged her friends. But her friends said it was too late.$$),
    ('1880', 4, $$Nozibele went back to the river alone. She found her necklace and began hurrying home. But, she got lost in the dark.$$),
    ('1880', 5, $$In the distance she saw light coming from a hut. She walked quickly towards it and knocked at the door.$$),
    ('1880', 6, $$To her surprise, a dog opened the door and said, "What do you want? " "I'm lost and I need a place to sleep," said Nozibele. "Come in, or I'll bite you! " said the dog. Nozibele went in.$$),
    ('1880', 7, $$The dog said, "Cook for me! " "But I've never cooked for a dog before," Nozibele answered. "Cook, or I'll bite you! " said the dog. Nozibele cooked some food for the dog.$$),
    ('1880', 8, $$Then the dog said, "Make the bed for me! " Nozibele answered, "I've never made a bed for a dog. " "Make the bed, or I'll bite you! " the dog said. Nozibele made the bed.$$),
    ('1880', 9, $$Every day she had to cook and sweep and wash for the dog. Then one day the dog said, "Nozibele, today I have to visit some friends. Sweep the house, cook the food and wash my things before I come back. "$$),
    ('1880', 10, $$As soon as the dog had gone, Nozibele took three hairs from her head. She put one hair under the bed, one behind the door, and one in the kraal. Then she ran home as fast as she could.$$),
    ('1880', 11, $$When the dog came back, he looked for Nozibele. "Nozibele, where are you? " he shouted. "I'm here, under the bed," said the first hair. "I'm here, behind the door," said the second hair. "I'm here, in the kraal," said the third hair.$$),
    ('1880', 12, $$The dog knew that Nozibele had tricked him. He ran and ran all the way to the village. But Nozibele's brothers were waiting there with big sticks. The dog turned and ran away and has never been seen since.$$),
    ('18892', 0, $$My father took me to town in our old blue car. We stopped at a big roundabout to wait for the lights to turn green.$$),
    ('18892', 1, $$I saw a lady walking on the side of the road. She was wearing a beautiful bright orange dress.$$),
    ('18892', 2, $$She had a big red belt around her waist.$$),
    ('18892', 3, $$In her hand, she carried a shiny little orange handbag.$$),
    ('18892', 4, $$She wore a pair of shiny orange high-heeled shoes.$$),
    ('18892', 5, $$She stopped and touched her long hair, which was held together in the middle with a hairpin.$$),
    ('18892', 6, $$As she fixed her hairpin, her handbag fell down. "Ouch," I said feeling bad for her.$$),
    ('18892', 7, $$The lady bent to pick up her handbag.$$),
    ('18892', 8, $$I saw long orange earrings as she cleaned the dust off her handbag.$$),
    ('18892', 9, $$The lights changed green, and our car drove off, but I kept looking behind.$$),
    ('18892', 10, $$"What are you looking at? " my father asked.$$),
    ('18892', 11, $$"At the lady in orange," I said. I thought of the colour orange all day.$$)
  ) AS v(source_id, page_index, text)
  JOIN books b
    ON b.source_platform = 'african_storybook' AND b.source_id = v.source_id
ON CONFLICT (book_id, page_index) DO NOTHING;

-- ───────── [적재검증] 트랜잭션 안 ─────────
-- (c) 적재 후 행 수 — 기대 478
SELECT count(*) AS rows_after FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892');
-- (d) 조인 실패로 누락된 source_id — 기대 0행
SELECT v.source_id FROM (VALUES ('10196'), ('10198'), ('10201'), ('10261'), ('10271'), ('10427'), ('10455'), ('10460'), ('10852'), ('12412'), ('13306'), ('13527'), ('13624'), ('13627'), ('13935'), ('14088'), ('14293'), ('14309'), ('14393'), ('14514'), ('14534'), ('14836'), ('14917'), ('14930'), ('14934'), ('14951'), ('14952'), ('14953'), ('15055'), ('15093'), ('15394'), ('15410'), ('15575'), ('15750'), ('15838'), ('15972'), ('16120'), ('16193'), ('16245'), ('16483'), ('16510'), ('16631'), ('17648'), ('18240'), ('18420'), ('18773'), ('1880'), ('18892')) AS v(source_id)
  WHERE NOT EXISTS (SELECT 1 FROM books b
     WHERE b.source_platform='african_storybook' AND b.source_id=v.source_id);
-- (e) source 라벨 분포 — 기대 manifest_txt_v1 1종 / 478행
SELECT bt.source, count(*) FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892')
  GROUP BY bt.source;
-- (f) page_index 축 검증 — 권마다 0부터 연속이어야 한다. 기대 0행(위반 없음)
SELECT b.source_id, min(bt.page_index) AS mn, max(bt.page_index) AS mx, count(*) AS n
  FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892')
  GROUP BY b.source_id HAVING min(bt.page_index) <> 0 OR max(bt.page_index) <> count(*)-1;
-- (g) 빈 면 행 수 — 기대 0 (D7: 빈 면도 text='' 로 적재)
SELECT count(*) AS empty_rows FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('10196', '10198', '10201', '10261', '10271', '10427', '10455', '10460', '10852', '12412', '13306', '13527', '13624', '13627', '13935', '14088', '14293', '14309', '14393', '14514', '14534', '14836', '14917', '14930', '14934', '14951', '14952', '14953', '15055', '15093', '15394', '15410', '15575', '15750', '15838', '15972', '16120', '16193', '16245', '16483', '16510', '16631', '17648', '18240', '18420', '18773', '1880', '18892') AND bt.text = '';

-- ───────── [종료] ─────────
-- (c)~(g)가 전부 기대값과 일치하면 아래 ROLLBACK; 을 COMMIT; 으로 바꿔 타이핑한다.
ROLLBACK;
